package org.mockito.internal.util;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.cglib.proxy.Callback;
import org.mockito.cglib.proxy.Factory;
import org.mockito.exceptions.misusing.NotAMockException;
import org.mockito.internal.InvocationNotifierHandler;
import org.mockito.internal.MockHandler;
import org.mockito.internal.MockHandlerInterface;
import org.mockito.internal.creation.MethodInterceptorFilter;
import org.mockito.internal.creation.MockSettingsImpl;
import org.mockito.internal.creation.callbacks.MockHandler;
import org.mockito.internal.creation.jmock.ClassImposterizer;
import org.mockito.internal.internal.ClassImposterizer;
import org.mockito.internal.internal.LenientCopyTool;
import org.mockito.internal.settings.MockSettingsImpl;
import org.mockito.internal.util.creation.MethodInterceptorFilter;
import org.mockito.internal.util.reflection.LenientCopyTool;
import org.mockito.internal.validation.exceptions.InvalidUseOfSettingsException;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class MockUtil_createMock_TriageGen1Test {

    private MockCreationValidator creationValidator;
    private MockUtil mockUtil;
    private MockSettingsImpl settings;

    @Before
    public void setUp() {
        creationValidator = mock(MockCreationValidator.class);
        mockUtil = new MockUtil(creationValidator);
        settings = mock(MockSettingsImpl.class);
    }

    @Test
    public void testCreateMock_BasicSuccess() {
        Class<List> clazz = List.class;
        when(settings.getExtraInterfaces()).thenReturn(null);
        when(settings.isSerializable()).thenReturn(false);
        when(settings.getSpiedInstance()).thenReturn(null);

        List result = mockUtil.createMock(clazz, settings);

        assertNotNull(result);
        verify(creationValidator).validateType(clazz);
        verify(creationValidator).validateExtraInterfaces(clazz, null);
        verify(creationValidator).validateMockedType(clazz, null);
        verify(settings).initiateMockName(clazz);
    }

    @Test
    public void testCreateMock_WithExtraInterfacesAndSerializable() {
        Class<List> clazz = List.class;
        Class<?>[] extraInterfaces = new Class<?>[]{Runnable.class};

        when(settings.getExtraInterfaces()).thenReturn(extraInterfaces);
        when(settings.isSerializable()).thenReturn(true);
        when(settings.getSpiedInstance()).thenReturn(null);

        List result = mockUtil.createMock(clazz, settings);

        assertNotNull(result);
        // Note: Internal ClassImposterizer logic is hard to verify without real bytecode manipulation, 
        // but we ensure the path through ancillaryTypes (concat) is covered.
        verify(settings).initiateMockName(clazz);
    }

    @Test
    public void testCreateMock_WithSpiedInstance() {
        Class<List> clazz = List.class;
        List spiedInstance = mock(List.class);

        when(settings.getExtraInterfaces()).thenReturn(null);
        when(settings.isSerializable()).thenReturn(false);
        when(settings.getSpiedInstance()).thenReturn(spiedInstance);

        List result = mockUtil.createMock(clazz, settings);

        assertNotNull(result);
        verify(creationValidator).validateMockedType(clazz, spiedInstance);
        // LenientCopyTool.copyToMock is called internally
    }

    @Test
    public void testCreateMock_ValidationFailure_Type() throws Exception {
        Class<List> clazz = List.class;
        doThrow(new InvalidUseOfSettingsException()).when(creationValidator).validateType(clazz);

        try {
            mockUtil.createMock(clazz, settings);
            fail("Should have thrown exception");
        } catch (InvalidUseOfSettingsException e) {
            // Success
        }
    }

    @Test
    public void testCreateMock_ValidationFailure_ExtraInterfaces() throws Exception {
        Class<List> clazz = List.class;
        when(settings.getExtraInterfaces()).thenReturn(null);
        doThrow(new InvalidUseOfSettingsException()).when(creationValidator).validateExtraInterfaces(eq(clazz), any());

        try {
            mockUtil.createMock(clazz, settings);
            fail("Should have thrown exception");
        } catch (InvalidUseOfSettingsException e) {
            // Success
        }
    }

    @Test
    public void testCreateMock_ValidationFailure_MockedType() throws Exception {
        Class<List> clazz = List.class;
        Object spied = new Object();
        when(settings.getSpiedInstance()).thenReturn(spied);
        doThrow(new InvalidUseOfSettingsException()).when(creationValidator).validateMockedType(clazz, spied);

        try {
            mockUtil.createMock(clazz, settings);
            fail("Should have thrown exception");
        } catch (InvalidUseOfSettingsException e) {
            // Success
        }
    }

    @Test
    public void testCreateMock_SerializableWithNoExtraInterfaces() {
        Class<List> clazz = List.class;
        when(settings.getExtraInterfaces()).thenReturn(null);
        when(settings.isSerializable()).thenReturn(true);
        when(settings.getSpiedInstance()).thenReturn(null);

        List result = mockUtil.createMock(clazz, settings);

        assertNotNull(result);
    }

    @Test
    public void testCreateMock_NonSerializableWithExtraInterfaces() {
        Class<List> clazz = List.class;
        Class<?>[] extra = new Class<?>[]{Runnable.class};
        when(settings.getExtraInterfaces()).thenReturn(extra);
        when(settings.isSerializable()).thenReturn(false);
        when(settings.getSpiedInstance()).thenReturn(null);

        List result = mockUtil.createMock(clazz, settings);

        assertNotNull(result);
    }
}
